/*
https://openprocessing.org/sketch/2307323
#minacoding #generativeart #creativecoding #p5js
*/

const FPS = 60;
const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);

const boundary = {w: 300, h: 100}; // 3:1 scale

function setup() {
  createCanvas(400, 400);
  // pixelDensity(1);
  describe("x header image: suggesting to leave x #leavex");
  frameRate(FPS);
  background(0, 0, 8);
}

function draw() {
	fill(CLRS[0]);
	const x = (width-boundary.w)/2;
	const y = (height-boundary.h)/2;
	rect(x, y, boundary.w, boundary.h)
  // // noLoop() removed for animation

	// --> lines
	stroke(CLRS[4])
	strokeWeight(1);
	for (let yy = y + 2, t = 0; yy < y + boundary.h; yy += 4, t += 0.15) {
		mLine(x + 1, yy, x + boundary.w - 2, yy, t);  
	}

	// --> text message	
	const s = 28;
	stroke(CLRS[2])
	strokeWeight(2);
	// #
	mLine(x + s, y, x + s, y + boundary.h * 0.8, 1);                  // |
	mLine(x + 2*s, y + boundary.h * 0.2, x + 2*s, y + boundary.h, 2); // |
	mLine(x, y + boundary.h * 0.5 - s/2, x + 2.5*s, y + boundary.h * 0.5 - s/2, 3);     // -
	mLine(x + s/2, y + boundary.h * 0.5 + s/2, x + 6.25*s, y + boundary.h * 0.5 + s/2, 4, 8); // ------
	// L
	mLine(x + 3*s, y, x + 3*s, y + boundary.h * 0.5 + s/2, 5); // |
	// E
	mLine(x + 4*s, y + boundary.h * 0.5 - s/2, x + 4*s, y + boundary.h * 0.5 + 1.5*s, 6);
	mLine(x + 4*s, y + boundary.h * 0.5 - s/2, x + 5*s, y + boundary.h * 0.5 - s/2, 7);
	mLine(x + 4*s, y + boundary.h * 0.5 + 1.5*s, x + 5*s, y + boundary.h * 0.5 + 1.5*s, 8);
	// A
	mLine(x + 5*s, y + boundary.h * 0.5 + 1.5*s, x + 5.75*s, y + boundary.h * 0.5 - s, 9);
	// AV
	mLine(x + 5.75*s, y + boundary.h * 0.5 - s, x + 6.75*s, y + boundary.h * 0.5 + 2*s, 10);
	// V
	mLine(x + 6.75*s, y + boundary.h * 0.5 + 2*s, x + 7.5*s, y + boundary.h * 0.5 - s/2, 11);
	// E
	mLine(x + 7.5*s, y + boundary.h * 0.5 - s/2, x + 8.5*s, y + boundary.h * 0.5 - s/2, 12);     // -
	mLine(x + 7.5*s, y + boundary.h * 0.5 - s/2, x + 7.5*s, y + boundary.h * 0.5 + 1.5*s, 13);   // |
	mLine(x + 7.5*s, y + boundary.h * 0.5 + s/2, x + 8.5*s, y + boundary.h * 0.5 + s/2, 14);     // -
	mLine(x + 7.5*s, y + boundary.h * 0.5 + 1.5*s, x + 8.5*s, y + boundary.h * 0.5 + 1.5*s, 15); // -
	// X
	mLine(x + 8.5*s, y + boundary.h, x + 10.5*s, y, 16);   // /
	mLine(x + 8.5*s, y, x + 10.5*s, y + boundary.h, 17);   // /

  showTitle("#minacoding 24/26 X Header Image: #leavex")
}

function mLine(x1, y1, x2, y2, s, d = 1.5) {
	const t = frameCount / FPS;
	if (t < s) return;

	let xx = x2, yy = y2;
	if (t < s+d) {
		// lerp
		const lf = myEasingFunction((t-s)/(d)); // fract(f); // TODO use d
		xx = lerp(x1, x2, fract(lf))
		yy = lerp(y1, y2, fract(lf))
	}
	line(x1, y1, xx, yy);
}

function myEasingFunction(t) {
    return t * t * t;
}

function showTitle(msg) {
	push();
  stroke(0);
	strokeWeight(2);
  fill(255);
  text(msg, 2, 12);
  pop();
}
